/*
 * Native-classic R6 mesh decoder.
 * Mesh payloads are copied from the supplied BloxLocalPlayer client content
 * (character3.rbxm companion meshes) and decoded locally in the browser.
 * No native client/runtime is launched by this module.
 */
const MESH_DATA = Object.freeze({"head":"","torso":"","leftarm":"","rightarm":"","leftleg":"","rightleg":""});

const NAME_MAP = Object.freeze({
    "Head":"head",
    "head":"head",
    "body":"torso",
    "Torso":"torso",
    "LeftArm":"leftarm",
    "Left Arm":"leftarm",
    "RightArm":"rightarm",
    "Right Arm":"rightarm",
    "LeftLeg":"leftleg",
    "Left Leg":"leftleg",
    "RightLeg":"rightleg",
    "Right Leg":"rightleg"
});

const CACHE = new Map();

function decodeBase64(value) {
    const raw = atob(value);
    const out = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
    return out;
}

function readRobloxMesh(bytes) {
    const signature = new TextDecoder().decode(bytes.subarray(0, 13));
    if (signature !== "version 2.00\n") {
        throw new Error(`Unsupported classic Roblox mesh: ${JSON.stringify(signature)}`);
    }

    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    let offset = 13;
    const headerSize = view.getUint16(offset, true); offset += 2;
    const vertexSize = view.getUint8(offset++);
    const faceSize = view.getUint8(offset++);
    const vertexCount = view.getUint32(offset, true); offset += 4;
    const faceCount = view.getUint32(offset, true); offset += 4;

    if (headerSize !== 12 || vertexSize < 32 || faceSize !== 12) {
        throw new Error(`Unexpected classic mesh layout h=${headerSize} v=${vertexSize} f=${faceSize}`);
    }

    const positions = new Float32Array(vertexCount * 3);
    const normals = new Float32Array(vertexCount * 3);
    const uvs = new Float32Array(vertexCount * 2);

    for (let i = 0; i < vertexCount; i++) {
        const p = offset + i * vertexSize;
        positions[i*3+0] = view.getFloat32(p+0, true);
        positions[i*3+1] = view.getFloat32(p+4, true);
        positions[i*3+2] = view.getFloat32(p+8, true);
        normals[i*3+0] = view.getFloat32(p+12, true);
        normals[i*3+1] = view.getFloat32(p+16, true);
        normals[i*3+2] = view.getFloat32(p+20, true);
        uvs[i*2+0] = view.getFloat32(p+24, true);
        uvs[i*2+1] = 1 - view.getFloat32(p+28, true);
    }

    offset += vertexCount * vertexSize;
    const indices = vertexCount > 65535
        ? new Uint32Array(faceCount * 3)
        : new Uint16Array(faceCount * 3);

    for (let i = 0; i < faceCount; i++) {
        const p = offset + i * faceSize;
        indices[i*3+0] = view.getUint32(p+0, true);
        indices[i*3+1] = view.getUint32(p+4, true);
        indices[i*3+2] = view.getUint32(p+8, true);
    }

    return {positions, normals, uvs, indices};
}


function prepareClassicR6FaceGroups(THREE, geometry) {
    const position = geometry.getAttribute("position");
    const normal = geometry.getAttribute("normal");
    const index = geometry.index;

    if (!position || !normal || !index) return geometry;

    geometry.computeBoundingBox();
    const box = geometry.boundingBox;
    const min = box.min;
    const max = box.max;
    const sx = Math.max(1e-6, max.x - min.x);
    const sy = Math.max(1e-6, max.y - min.y);
    const sz = Math.max(1e-6, max.z - min.z);

    // Native classic limb meshes carry their own legacy UV atlas. Clothing is
    // not that atlas: each shirt/pants crop must cover one complete body face.
    // Re-project each vertex to 0..1 face UVs, matching THREE.BoxGeometry.
    const uv = new Float32Array(position.count * 2);

    function classify(nx, ny, nz) {
        const ax = Math.abs(nx), ay = Math.abs(ny), az = Math.abs(nz);
        if (ax >= ay && ax >= az) return nx >= 0 ? 0 : 1; // +X / -X
        if (ay >= ax && ay >= az) return ny >= 0 ? 2 : 3; // +Y / -Y
        return nz >= 0 ? 4 : 5;                           // +Z / -Z
    }

    for (let i = 0; i < position.count; i++) {
        const x = position.getX(i), y = position.getY(i), z = position.getZ(i);
        const face = classify(normal.getX(i), normal.getY(i), normal.getZ(i));
        let u = 0, v = 0;
        switch (face) {
            case 0: // +X
                u = (max.z - z) / sz;
                v = (y - min.y) / sy;
                break;
            case 1: // -X
                u = (z - min.z) / sz;
                v = (y - min.y) / sy;
                break;
            case 2: // +Y
                u = (x - min.x) / sx;
                v = (max.z - z) / sz;
                break;
            case 3: // -Y
                u = (x - min.x) / sx;
                v = (z - min.z) / sz;
                break;
            case 4: // +Z / front
                u = (x - min.x) / sx;
                v = (y - min.y) / sy;
                break;
            case 5: // -Z / back
                u = (max.x - x) / sx;
                v = (y - min.y) / sy;
                break;
        }
        uv[i * 2] = Math.max(0, Math.min(1, u));
        uv[i * 2 + 1] = Math.max(0, Math.min(1, v));
    }
    geometry.setAttribute("uv", new THREE.BufferAttribute(uv, 2));

    // Group triangles by their dominant outward face normal. This gives the
    // clothing system six independently addressable materials on the beveled
    // native R6 geometry instead of rendering the whole limb with material 0.
    const source = index.array;
    const buckets = Array.from({ length: 6 }, () => []);
    for (let i = 0; i < source.length; i += 3) {
        const a = source[i], b = source[i + 1], c = source[i + 2];
        const nx = (normal.getX(a) + normal.getX(b) + normal.getX(c)) / 3;
        const ny = (normal.getY(a) + normal.getY(b) + normal.getY(c)) / 3;
        const nz = (normal.getZ(a) + normal.getZ(b) + normal.getZ(c)) / 3;
        buckets[classify(nx, ny, nz)].push(a, b, c);
    }

    const IndexArray = source.constructor;
    const reordered = new IndexArray(source.length);
    let write = 0;
    geometry.clearGroups();
    for (let materialIndex = 0; materialIndex < 6; materialIndex++) {
        const bucket = buckets[materialIndex];
        if (!bucket.length) continue;
        reordered.set(bucket, write);
        geometry.addGroup(write, bucket.length, materialIndex);
        write += bucket.length;
    }
    geometry.setIndex(new THREE.BufferAttribute(reordered, 1));
    return geometry;
}

export function getNativeR6Geometry(THREE, partName) {
    const key = NAME_MAP[String(partName)] || null;
    if (!key || !MESH_DATA[key]) return null;

    if (!CACHE.has(key)) {
        const decoded = readRobloxMesh(decodeBase64(MESH_DATA[key]));
        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute("position", new THREE.BufferAttribute(decoded.positions, 3));
        geometry.setAttribute("normal", new THREE.BufferAttribute(decoded.normals, 3));
        geometry.setAttribute("uv", new THREE.BufferAttribute(decoded.uvs, 2));
        geometry.setIndex(new THREE.BufferAttribute(decoded.indices, 1));
        prepareClassicR6FaceGroups(THREE, geometry);

        // Keep the decoded classic head at its authored ~1.2-stud size.
        // The previous v9 prototype applied the character3 SpecialMesh 1.25
        // multiplier a second time here, making the playable head visibly too large.

        geometry.computeBoundingBox();
        geometry.computeBoundingSphere();
        geometry.userData.__bloxNativeClassicR6 = true;
        CACHE.set(key, geometry);
    }

    return CACHE.get(key).clone();
}

export function getNativeR6MeshInfo() {
    return Object.freeze({
        source: "supplied BloxLocalPlayer character3.rbxm companion meshes",
        format: "Roblox mesh version 2.00",
        parts: Object.keys(MESH_DATA)
    });
}
